mapper.select:
select a.id,a.allot_numbers,a.receive_time,a.receive_user_id,
a.receive_dep_name,a.create_by,a.creator_id,a.creator_type,a.remarks,a.status,a.over_dep_name,
c.id as c_id,c.`name`,c.serial_number,c.type_id,c.status as propertyStatus,
a.process_instance_id
from property_allot a
inner join property_allot_relation b on a.id=b.allot_id
inner join property_detailed c on b.property_id=c.id


        and a.receive_time=#{param.receiveTime}


        and a.over_dep_id=#{param.overDepId}


        and a.receive_dep_id=#{param.receiveDepId}


        and a.status=#{param.status}


        and c.type_id=#{param.typeId}


        and a.type= #{param.type}


        and (a.allot_numbers like CONCAT('%',#{param.keyword},'%')
        or c.name like CONCAT('%',#{param.keyword},'%'))


group by a.id
order by a.receive_time desc

select
c.`name`,c.serial_number
from property_allot a
inner join property_allot_relation b on a.id=b.allot_id
inner join property_detailed c on b.property_id=c.id
where a.id=#{id}

    and a.receive_time=#{param.receiveTime}


    and a.over_dep_id=#{param.overDepId}


    and a.receive_dep_id=#{param.receiveDepId}


    and a.status=#{param.status}


    and c.type_id=#{param.typeId}


    and a.type= #{param.type}


    and (a.allot_numbers like CONCAT('%',#{param.keyword},'%')
    or c.name like CONCAT('%',#{param.keyword},'%'))

group by c.id
order by a.receive_time desc

select property_id
from property_allot_relation
where allot_numbers = #{allotNumbers}
